import sys
from math import gcd

def process_tasks(tasks):
    a = []
    results = []
    for task in tasks:
        if task[0] == 1:
            a.append(task[1])
        else:
            x, k, s = task[1:]
            max_xor = -1
            best_v = -1
            for v in a:
                if k % gcd(x, v) == 0 and x + v <= s:
                    current_xor = x ^ v
                    if current_xor > max_xor:
                        max_xor = current_xor
                        best_v = v
            results.append(best_v)
    return results

def main():
    import sys
    input = sys.stdin.read().split()
    q = int(input[0])
    tasks = []
    idx = 1
    for _ in range(q):
        if input[idx] == '1':
            tasks.append((1, int(input[idx + 1])))
            idx += 2
        else:
            tasks.append((2, int(input[idx + 1]), int(input[idx + 2]), int(input[idx + 3])))
            idx += 4
    results = process_tasks(tasks)
    for result in results:
        print(result)

main()
